-- Student Engagement Analytics (student-engagement-analytics) v1 — postgres
-- Synthetic sample data, CC0-1.0. Deterministic: the same spec and seed produce this byte for byte.
-- seed: student-engagement-analytics:1
-- Tables in dependency order; foreign keys are added after the data.

BEGIN;

CREATE TABLE "courses" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "course_name" varchar(36) NOT NULL,
    "course_code" varchar(120) NOT NULL,
    "credits" integer NOT NULL
);


select * from grading_periods;
select * from courses;
select * from students;
select * from enrollments;
select * from attendance;
select * from quiz_performance;




CREATE TABLE "grading_periods" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "start_date" date NOT NULL,
    "end_date" date NOT NULL,
    "term" varchar(39) NOT NULL
);

CREATE TABLE "students" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "first_name" varchar(60) NOT NULL,
    "last_name" varchar(60) NOT NULL,
    "email" varchar(120) NOT NULL,
    "enrollment_date" date NOT NULL
);

CREATE TABLE "enrollments" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "student_id" integer NOT NULL,
    "course_id" integer NOT NULL,
    "enrollment_date" date NOT NULL,
    "status" varchar(9) NOT NULL,
    "completion_date" date
);

CREATE TABLE "attendance" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "enrollment_id" integer NOT NULL,
    "date" date NOT NULL,
    "status" varchar(7) NOT NULL,
    "attendance_type" varchar(8) NOT NULL,
    "duration_minutes" integer NOT NULL
);

CREATE TABLE "quiz_performance" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "enrollment_id" integer NOT NULL,
    "grading_period_id" integer NOT NULL,
    "score" numeric(14,2) NOT NULL,
    "quiz_date" date NOT NULL,
    "max_score" numeric(14,2) NOT NULL,
    "attempt_number" integer NOT NULL
);

SELECT setval(pg_get_serial_sequence('"courses"', 'id'), (SELECT MAX("id") FROM "courses"));

SELECT setval(pg_get_serial_sequence('"grading_periods"', 'id'), (SELECT MAX("id") FROM "grading_periods"));

SELECT setval(pg_get_serial_sequence('"students"', 'id'), (SELECT MAX("id") FROM "students"));

SELECT setval(pg_get_serial_sequence('"enrollments"', 'id'), (SELECT MAX("id") FROM "enrollments"));

SELECT setval(pg_get_serial_sequence('"attendance"', 'id'), (SELECT MAX("id") FROM "attendance"));

SELECT setval(pg_get_serial_sequence('"quiz_performance"', 'id'), (SELECT MAX("id") FROM "quiz_performance"));

ALTER TABLE "enrollments" ADD CONSTRAINT "fk_enrollments_student_id" FOREIGN KEY ("student_id") REFERENCES "students" ("id");
ALTER TABLE "enrollments" ADD CONSTRAINT "fk_enrollments_course_id" FOREIGN KEY ("course_id") REFERENCES "courses" ("id");
ALTER TABLE "attendance" ADD CONSTRAINT "fk_attendance_enrollment_id" FOREIGN KEY ("enrollment_id") REFERENCES "enrollments" ("id");
ALTER TABLE "quiz_performance" ADD CONSTRAINT "fk_quiz_performance_enrollment_id" FOREIGN KEY ("enrollment_id") REFERENCES "enrollments" ("id");
ALTER TABLE "quiz_performance" ADD CONSTRAINT "fk_quiz_performance_grading_period_id" FOREIGN KEY ("grading_period_id") REFERENCES "grading_periods" ("id");

COMMIT;








select * from grading_periods;
select * from courses;
select * from students;
select * from enrollments;
select * from attendance;
select * from quiz_performance;


--(1)enrolement volume per course and there credit weight impact 

SELECT
c.course_name,
c.credits,
COUNT(e.id) AS total_enrollments
FROM courses c
LEFT JOIN enrollments e ON c.id = e.course_id
GROUP BY c.id, c.course_name, c.credits
ORDER BY total_enrollments DESC;




--(2)the platform-wide distribution of enrollment statuses (active, completed, dropped) and the overall churn rate


SELECT
status,
COUNT(*) AS status_count,
ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (), 2) AS percentage_share
FROM enrollments
GROUP BY status;



-- (3)courses exhibit an alarming dropout rate exceeding 15% among offerings with at least 5 registered students

SELECT 
c.course_name,
COUNT(e.id) AS total_enrolled,
SUM(CASE WHEN e.status = 'dropped' THEN 1 ELSE 0 END) AS dropped_students,
ROUND(100.0 * SUM(CASE WHEN e.status = 'dropped' THEN 1 ELSE 0 END) / COUNT(e.id), 2) 
AS churn_rate_pct
FROM courses c
JOIN enrollments e ON c.id = e.course_id
GROUP BY c.course_name
HAVING COUNT(e.id) >= 5
ORDER BY churn_rate_pct DESC;




--(4)For completed enrollments, what is the average turnaround duration in days from initial registration to completion


select  c.course_name, count(e.id) as total_member,
round(avg(e.completion_date - e.enrollment_date),1)  as days_of_completion 
from courses c join enrollments e on e.course_id = c.id 
where  e.status = 'completed' and e.completion_date IS NOT NULL
group by c.course_name 
order by days_of_completion desc
;


--(5) new student onboarding trended month-over-month across registration intake cohorts

SELECT 
  EXTRACT(YEAR FROM enrollment_date) AS cohort_year,
  EXTRACT(MONTH FROM enrollment_date) AS cohort_month,
  COUNT(id) AS new_students_onboarded
FROM students
GROUP BY 1, 2
ORDER BY 1, 2;
--(second method of same question )
SELECT 
DATE_TRUNC('month', enrollment_date)::DATE AS cohort_month,
COUNT(id) AS new_students_onboarded
FROM students
GROUP BY cohort_month
ORDER BY cohort_month;



--(6)the overall ratio between Present, Late, and Absent events across all recorded sessions

select status,
count(*) as total_record,
round(100.0*count(*)/sum(count(*))over(),2) as ratio_of_record_session from attendance
group by status ;



--(7)attendance punctuality and average duration spent vary across Lecture, Lab, and Tutorial formats

  
SELECT 
attendance_type,
COUNT(*) AS total_sessions,
ROUND(100.0 * SUM(CASE WHEN status = 'present' THEN 1 ELSE 0 END) / COUNT(*), 2) AS 
present_pct,
ROUND(AVG(duration_minutes), 1) AS avg_duration_spent
FROM attendance
GROUP BY attendance_type;


--(8) specific courses command the highest average learning duration per attended session

SELECT 
c.course_name,
ROUND(AVG(a.duration_minutes), 2) AS avg_minutes_per_session,
SUM(a.duration_minutes) / 60 AS total_study_hours
FROM attendance a
JOIN enrollments e ON a.enrollment_id = e.id
JOIN courses c ON e.course_id = c.id
WHERE a.status IN ('present', 'late')
GROUP BY c.course_name
ORDER BY avg_minutes_per_session DESC;


--(9)Does higher lecture attendance directly drive higher quiz scores at the individual enrollment level





WITH att_summary AS (
SELECT 
enrollment_id,
ROUND(100.0 * SUM(CASE WHEN status = 'present' THEN 1 ELSE 0 END) / COUNT(*), 2) AS 
att_rate
FROM attendance
GROUP BY enrollment_id
),
quiz_summary AS (
SELECT 
enrollment_id,
ROUND(AVG((score / max_score) * 100), 2) AS avg_test_score
FROM quiz_performance
GROUP BY enrollment_id
)
SELECT 
a.enrollment_id,
a.att_rate,
q.avg_test_score
FROM att_summary a
JOIN quiz_summary q ON a.enrollment_id = q.enrollment_id;


--(10) proportion of students enroll in multiple courses, and what is their active vs. completed course load


SELECT 
student_id,
COUNT(course_id) AS enrolled_courses_count,
SUM(CASE WHEN status = 'active' THEN 1 ELSE 0 END) AS active_courses,
SUM(CASE WHEN status = 'completed' THEN 1 ELSE 0 END) AS completed_courses
FROM enrollments
GROUP BY student_id
HAVING COUNT(course_id) > 1
ORDER BY enrolled_courses_count DESC;






